css:
/* Fabrang Legend Custom Style */
.detail-page {
  background: #fff;
  font-family: 'PingFang SC', 'STHeiti', sans-serif;
  color: #333;
  width: 1000px;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}

.section {
  display: block;
  position: relative;
  background-size: cover;
  background-position: center;
  overflow: hidden;
  width: 1000px;
  margin: 0;
  padding: 0;
  border: none;
  line-height: normal;
}

.section h1, .section h2, .section h3, .section p {
  margin-top: 0; /* Prevent margin collapse pushing sections */
}

.section img {
  display: block;
  max-width: 100%;
  margin: 0;
  padding: 0;
  border: none;
}

/* Hero */
.hero .badge-container {
  position: absolute;
  top: 40px;
  right: 60px;
  text-align: center;
  color: #c9a26b;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.hero .content-center {
  position: absolute;
  left: 60px;
  bottom: 120px;
}
.hero .main-title {
  font-size: 84px; margin: 0; color: #111; letter-spacing: 2px; font-weight: 800; line-height: 1.1;
}
.hero .main-title small {
  font-size: 28px; color: #777; display: block; margin-top: 10px; font-weight: 300; letter-spacing: 8px; text-transform: uppercase;
}
.hero .sub-title {
  font-size: 32px; color: #444; margin: 35px 0; border-left: 6px solid #c9a26b; padding-left: 20px; font-weight: 500;
}
.hero .highlights {
  display: flex; gap: 20px; margin-top: 40px;
}
.hero .highlights span {
  background: #111; color: #fff; padding: 10px 24px; border-radius: 2px; font-size: 18px; letter-spacing: 1px;
}

/* Alcohol */
.alcohol {
  display: flex; align-items: center; justify-content: flex-end; padding-right: 80px;
}
.alcohol .float-text {
  background: rgba(255,255,255,0.98); padding: 60px; border-radius: 4px; max-width: 480px; box-shadow: 0 30px 60px rgba(0,0,0,0.12); border-top: 8px solid #b01a1a;
}
.alcohol h2 {
  font-size: 52px; margin: 0 0 30px; color: #b01a1a; line-height: 1.3; font-weight: 800;
}
.alcohol p {
  font-size: 22px; color: #555; line-height: 1.8; margin-bottom: 40px;
}
.alcohol .tag {
  display: inline-block; background: #b01a1a; color: #fff; padding: 14px 35px; font-weight: bold; border-radius: 4px; font-size: 24px; letter-spacing: 1px;
}

/* Origin */
.origin {
  background: #f8f8f8; display: flex; flex-direction: column; justify-content: center; align-items: center; padding: 100px 0;
}
.origin h2 {
  font-size: 48px; margin-bottom: 80px; color: #111; font-weight: 800; text-align: center;
}
.origin .grid {
  display: flex; gap: 40px; width: 900px;
}
.origin .card {
  flex: 1; background: #fff; padding: 60px; border-radius: 4px; transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
  border: 1px solid rgba(0,0,0,0.03);
}
.origin .card:hover { transform: translateY(-12px); box-shadow: 0 25px 50px rgba(0,0,0,0.1) !important; }
.origin h3 {
  font-size: 32px; margin-bottom: 30px; color: #c9a26b; font-weight: 700;
}
.origin p {
  color: #666; line-height: 2; font-size: 20px;
}

/* Flavor */
.flavor .flavor-overlay {
  position: absolute; width: 100%; height: 100%; background: linear-gradient(to right, rgba(255,255,255,1) 30%, rgba(255,255,255,0.7) 50%, rgba(0,0,0,0));
  padding: 100px; display: flex; flex-direction: column; justify-content: center;
}
.flavor h2 {
  font-size: 64px; color: #b01a1a; margin-bottom: 40px; font-weight: 800; letter-spacing: -1px;
}
.flavor .flavor-notes {
  display: flex; gap: 15px; margin-bottom: 50px;
}
.flavor .item {
  background: #fff; padding: 14px 28px; border-radius: 30px; font-weight: 700; color: #111; box-shadow: 0 4px 10px rgba(0,0,0,0.05); border: 1px solid #eee;
}
.flavor .flavor-p {
  max-width: 550px; font-size: 24px; color: #333; line-height: 1.8; border-left: 4px solid #b01a1a; padding-left: 24px;
}

/* Pairing */
.pairing {
  display: flex; 
  align-items: center; 
  justify-content: flex-end; 
  padding-right: 60px;
}
.pairing-card { 
  background: rgba(255,255,255,0.92); 
  color: #111; 
  padding: 60px; 
  border-radius: 4px; 
  box-shadow: 0 30px 60px rgba(0,0,0,0.2); 
  width: 480px; 
  backdrop-filter: blur(10px);
}
.pairing-title { 
  font-size: 48px; 
  margin-bottom: 20px; 
  font-weight: 800; 
  color: #111;
  text-shadow: none;
}
.pairing-badge { 
  background: #c9a26b; 
  color: #fff; 
  display: inline-block; 
  padding: 8px 20px; 
  border-radius: 2px; 
  margin-bottom: 40px; 
  font-size: 18px; 
  letter-spacing: 2px; 
  font-weight: bold; 
}
.pairing-list { 
  list-style: none; 
  padding: 0; 
  display: grid; 
  grid-template-columns: 1fr 1fr; 
  gap: 30px; 
}
.pairing-list li { 
  font-size: 24px; 
  font-weight: 600; 
  color: #333; 
  display: flex; 
  align-items: center; 
}
.pairing-list li::before { 
  content: '✓'; 
  color: #c9a26b; 
  margin-right: 12px; 
  font-size: 24px; 
}

/* NFC */
.nfc { background: #111; color: #fff; display: flex; align-items: center; justify-content: center; gap: 80px; }
.nfc-icon-wrap { width: 140px; height: 140px; border: 2px dashed #c9a26b; border-radius: 50%; display: flex; align-items: center; justify-content: center; animation: pulse 2s infinite; }
.nfc-icon-wrap img { width: 70px; }
.nfc-text h2 { font-size: 44px; margin-bottom: 20px; color: #c9a26b; font-weight: 700; }
.nfc-text p { font-size: 22px; color: #aaa; max-width: 550px; line-height: 1.7; }
@keyframes pulse { 0% { box-shadow: 0 0 0 0 rgba(201, 162, 107, 0.4); } 70% { box-shadow: 0 0 0 20px rgba(201, 162, 107, 0); } 100% { box-shadow: 0 0 0 0 rgba(201, 162, 107, 0); } }

/* Specs */
.specs-table { width: 100%; border-collapse: collapse; font-size: 22px; }
.specs-table th { text-align: left; padding: 35px; background: #fafafa; width: 240px; border-bottom: 1px solid #f0f0f0; color: #888; font-weight: 400; }
.specs-table td { padding: 35px; border-bottom: 1px solid #f0f0f0; color: #111; font-weight: 600; }
